#!/usr/bin/env python3
"""Generate scripts/demo/seed.sql: a fictional two-company portfolio for the
Properly demo account, used for marketing screenshots.

Everything is deterministic (fixed seed, uuid5 ids) so the seed can be re-run
after teardown.sql and produce the same rows. Nothing here is real: the
companies, addresses, people and figures are invented.

Run:  python3 scripts/demo/generate_seed.py > scripts/demo/seed.sql
"""
import random, uuid, datetime as dt, json

random.seed(7)
NS = uuid.UUID('de3d0000-0000-4000-8000-00000000f00d')
def uid(*parts):
    return str(uuid.uuid5(NS, '|'.join(str(p) for p in parts)))

U   = 'fb1e99c8-ef2f-4903-9bbf-588ead787a6d'        # demo auth user
C1  = 'de3d0000-0000-4000-8000-000000000001'        # Northgate Property Ltd
C2  = 'de3d0000-0000-4000-8000-000000000002'        # Harbour Lets Ltd
HC  = 'de3d0002-0000-4000-8000-000000000001'        # hostaway connection
MGR = 'de3d0003-0000-4000-8000-000000000001'        # STL manager
TODAY = dt.date(2026, 9, 7)

def q(v):
    if v is None: return 'null'
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, (int, float)): return repr(v)
    if isinstance(v, (dt.date, dt.datetime)): return "'" + v.isoformat() + "'"
    if isinstance(v, (dict, list)): return "'" + json.dumps(v).replace("'", "''") + "'::jsonb"
    return "'" + str(v).replace("'", "''") + "'"

out = []
def section(title): out.append(f"\n-- ── {title} " + "─" * max(0, 70 - len(title)))
def insert(table, rows, cols=None):
    if not rows: return
    cols = cols or list(rows[0].keys())
    out.append(f"insert into public.{table} ({', '.join(cols)}) values")
    # A key the row does not carry becomes DEFAULT, not NULL: an explicit null
    # overrides the column default and trips NOT NULL columns such as
    # tenancies.opening_arrears or properties.is_hmo.
    vals = [f"  ({', '.join(q(r[c]) if c in r else 'default' for c in cols)})" for r in rows]
    out.append(',\n'.join(vals) + ';')

def insert_compact(table, rows, cols, types, consts):
    """insert ... select <consts>, v.* from (values ...) with explicit casts, for
    the two bulk tables. Keeps the repeated constants out of every row."""
    if not rows: return
    const_cols = ', '.join(consts.keys()); const_vals = ', '.join(consts.values())
    casts = ', '.join(f"v.{c}::{types[c]}" for c in cols)
    out.append(f"insert into public.{table} ({const_cols}, {', '.join(cols)})\nselect {const_vals}, {casts} from (values")
    out.append(',\n'.join('  (' + ', '.join(q(r.get(c)) for c in cols) + ')' for r in rows))
    out.append(f") as v({', '.join(cols)});")

out.append("-- GENERATED by scripts/demo/generate_seed.py. Do not edit by hand.")
out.append(f"-- Demo user {U}. Teardown: scripts/demo/teardown.sql")

