def months(a, b):
    y, m = a.year, a.month
    while (y, m) <= (b.year, b.month):
        yield y, m
        m += 1
        if m == 13: y, m = y + 1, 1
def last_day(y, m): return (dt.date(y + (m == 12), (m % 12) + 1, 1) - dt.timedelta(days=1)).day
# One row per tenancy-month from Jan 2025 to the current month, expanded in
# SQL so the seed stays small. Overrides below turn a few months into the
# late / missed / part-paid cases the screenshots need.
out.append(f"""insert into public.rent_payments (property_id, user_id, tenancy_id, year, month, month_label, status, amount, expected_amount, due_date)
select t.property_id, t.user_id, t.id, extract(year from d)::int, extract(month from d)::int, to_char(d, 'Mon YYYY'), 'paid', t.rent_amount, t.rent_amount,
       least(d::date + (t.rent_due_day - 1), (d + interval '1 month - 1 day')::date)
from public.tenancies t
cross join lateral generate_series(greatest(date_trunc('month', t.tenancy_start), date '2025-01-01'), least(coalesce(t.tenancy_end, date '2026-09-07'), date '2026-09-07'), interval '1 month') d
where t.user_id = {q(U)};""")
def ovr(pk, y, m, status, amount, note=None):
    out.append(f"update public.rent_payments set status = {q(status)}, amount = {q(amount)}, notes = {q(note)} where property_id = {q(pid(pk))} and year = {y} and month = {m};")
ovr(3, 2026, 3, 'late', 695, 'Paid 9 days late')
ovr(3, 2026, 7, 'overdue', 0); ovr(3, 2026, 8, 'overdue', 0); ovr(3, 2026, 9, 'partial', 300, 'Part payment received 5 Sept')
ovr(7, 2026, 9, 'partial', 300, 'Tenant paid £300, balance promised 12 Sept')
ovr(2, 2025, 10, 'late', 850, 'Paid 6 days late')
